e, int cdmaSubscription, Integer instanceId) &#123; super(context); mContext = context; mPreferredNetworkType = preferredNetworkType; mPhoneType = RILConstants.NO_PHONE; mPhoneId = instanceId; ConnectivityManager cm = (ConnectivityManager)context.getSystemService( Context.CONNECTIVITY_SERVICE); mIsMobileNetworkSupported = cm.isNetworkSupported(ConnectivityManager.TYPE_MOBILE); // 新建response,indication，用于接收RILD的消息 mRadioResponse = new RadioResponse(this); mRadioIndication = new RadioIndication(this); mOemHookResponse = new OemHookResponse(this); mOemHookIndication = new OemHookIndication(this); mRilHandler = new RilHandler(); mRadioProxyDeathRecipient = new RadioProxyDeathRecipient(); .... // 获取RILD HAL服务 getRadioProxy(null); getOemHookProxy(null);&#125; getRadioProxy首先判断终端是否支持移动数据，如果没有移动数据（没有modem），则直接返回空；如果已经获取到了，则返回之前获取到的代理对象mRadioProxy。如果都不是，通过IRadio.getService来获取RILD服务的代理对象，接着向RILD注册回调函数mRadioResponse以及mRadioIndication,同时还需要注册RILD服务的死亡注册通知接收器，以便RILD异常退出后，RILJ能够收到该信息做相应的处理。 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647private IRadio getRadioProxy(Message result) &#123; if (!mIsMobileNetworkSupported) &#123; if (RILJ_LOGV) riljLog(&quot;getRadioProxy: Not calling getService(): wifi-only&quot;); if (result != null) &#123; AsyncResult.forMessage(result, null, CommandException.fromRilErrno(RADIO_NOT_AVAILABLE)); result.sendToTarget(); &#125; return null; &#125; if (mRadioProxy != null) &#123; return mRadioProxy; &#125; try &#123; mRadioProxy = IRadio.getService(HIDL_SERVICE_NAME[mPhoneId == null ? 0 : mPhoneId]); if (mRadioProxy != null) &#123; mRadioProxy.linkToDeath(mRadioProxyDeathRecipient, mRadioProxyCookie.incrementAndGet()); mRadioProxy.setResponseFunctions(mRadioResponse, mRadioIndication); &#125; else &#123; riljLoge(&quot;getRadioProxy: mRadioProxy == null&quot;); &#125; &#125; catch (RemoteException | RuntimeException e) &#123; mRadioProxy = null; riljLoge(&quot;RadioProxy getService/setResponseFunctions: &quot; + e); &#125; if (mRadioProxy == null) &#123; if (result != null) &#123; AsyncResult.forMessage(result, null, CommandException.fromRilErrno(RADIO_NOT_AVAILABLE)); result.sendToTarget(); &#125; // 此时RILD服务还无法获取到，则延迟几秒再次获取 mRilHandler.sendMessageDelayed( mRilHandler.obtainMessage(EVENT_RADIO_PROXY_DEAD, mRadioProxyCookie.incrementAndGet()), IRADIO_GET_SERVICE_DELAY_MILLIS); &#125; return mRadioProxy;&#125; 这里有一个问题，搜索Android源码并没有IRadio.java类，那么只能说同之前HwServiceMananger一样，这个类也是通过hidl-gen来产生的。看下IRadio.hal对应目录的Android.bp并没有定义生成规则，是不是在Android.mk里边了？搜了下，果然在： 123456789101112131415161718192021222324252627## Build IRadio.hal#GEN := $(intermediates)/android/hardware/radio/V1_0/IRadio.java$(GEN): $(HIDL)$(GEN): PRIVATE_HIDL := $(HIDL)$(GEN): PRIVATE_DEPS := $(LOCAL_PATH)/IRadio.hal$(GEN): PRIVATE_DEPS += $(LOCAL_PATH)/IRadioIndication.hal$(GEN): $(LOCAL_PATH)/IRadioIndication.hal$(GEN): PRIVATE_DEPS += $(LOCAL_PATH)/IRadioResponse.hal$(GEN): $(LOCAL_PATH)/IRadioResponse.hal$(GEN): PRIVATE_DEPS += $(LOCAL_PATH)/types.hal$(GEN): $(LOCAL_PATH)/types.hal$(GEN): PRIVATE_OUTPUT_DIR := $(intermediates)$(GEN): PRIVATE_CUSTOM_TOOL = \ $(PRIVATE_HIDL) -o $(PRIVATE_OUTPUT_DIR) \ -Ljava \ -randroid.hardware:hardware/interfaces \ -randroid.hidl:system/libhidl/transport \ android.hardware.radio@1.0::IRadio$(GEN): $(LOCAL_PATH)/IRadio.hal $(transform-generated-source)LOCAL_GENERATED_SOURCES += $(GEN) 可以简单的写成如下这个指令，其作用是生成一个Java层的类用于获取RILD的服务。 hidl-gen利用generateJava.cpp中的函数generateJava来自动生成对应的类 123hidl-gen -o $(PRIVATE_OUTPUT_DIR) -LJava -randroid.hardware:hardware/interfaces -randroid.hidl:system/libhidl/transport ` generateJava.cpp生成的IRadio.java大致结构如下（只写了几个关键函数）。绕来绕去，IRadio.getService("slot1")实际返回的是一个由HwBinder.getService返回的IHwBinder对象： 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556package android.hardware.radio;public interface IRaio extends android.os.IHwInterface &#123; public static final String kInterfaceName = &quot;android.hardware.radio::IRadio&quot;; static asInterface(android.os.IHwBinder binder) &#123; if (binder == null) &#123; return null; &#125; android.os.IHwInterface iface = binder.queryLocalInterface(kInterfaceName); if (iface != null &amp;&amp; iface instanceof IRaio) &#123; return (IRadio)iface; &#125; IRadio proxy = new IRadio.Proxy(binder); try &#123; for (String descriptor : proxy.interfaceChain()) &#123; if (descriptor.equals(kInterfaceName)) &#123; return proxy; &#125; &#125; &#125; catch (android.os.RemoteException e) &#123; &#125; return null; ... public static getService(String serviceName) throws android.os.RemoteException &#123; return IRadio.asInterface(android.os.HwBinder.getService( android.hardware.radio@1.0::IRadio, serviceName)); &#125; ... public static final class Proxy implements IRadio &#123; private android.os.IHwBinder mRemote; public Proxy(android.os.IHwBinder remote) &#123; mRemote = java.util.Objects.requireNonNull(remote); &#125; @Override public android.os.IHwBinder asBinder() &#123; return mRemote; &#125; &#125; ... &#125;&#125; 继续看看HwBinder.getService返回的是什么东东？原来是一个native函数调用。 12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849public abstract class HwBinder implements IHwBinder &#123; private static final String TAG = &quot;HwBinder&quot;; private static final NativeAllocationRegistry sNativeRegistry; public HwBinder() &#123; native_setup(); sNativeRegistry.registerNativeAllocation( this, mNativeContext); &#125; @Override public final native void transact( int code, HwParcel request, HwParcel reply, int flags) throws RemoteException; public abstract void onTransact( int code, HwParcel request, HwParcel reply, int flags) throws RemoteException; public native final void registerService(String serviceName) throws RemoteException; // native接口 public static native final IHwBinder getService( String iface, String serviceName) throws RemoteException, NoSuchElementException; // Returns address of the &quot;freeFunction&quot;. private static native final long native_init(); private native final void native_setup(); static &#123; long freeFunction = native_init(); sNativeRegistry = new NativeAllocationRegistry( HwBinder.class.getClassLoader(), freeFunction, 128 /* size */); &#125; private long mNativeContext;&#125; native层获取HAL服务，仍然是通过defaultServiceManager来获取服务的代理对象，从上面获取上下文服务ServiceManager的过程不难看出hardware::defaultServiceManager()-&gt;get("android.hardware.radio@1.0::IRadio", "slot1")返回的实际上是一个与RILD服务binder代理对象BpHwBinder(handle)（handle由注册服务时binder驱动自动生成）： 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100static jobject JHwBinder_native_getService( JNIEnv *env, jclass /* clazzObj */, jstring ifaceNameObj, jstring serviceNameObj) &#123; using ::android::hidl::base::V1_0::IBase; using ::android::hidl::manager::V1_0::IServiceManager; if (ifaceNameObj == NULL) &#123; jniThrowException(env, &quot;java/lang/NullPointerException&quot;, NULL); return NULL; &#125; if (serviceNameObj == NULL) &#123; jniThrowException(env, &quot;java/lang/NullPointerException&quot;, NULL); return NULL; &#125; auto manager = hardware::defaultServiceManager(); if (manager == nullptr) &#123; LOG(ERROR) &lt;&lt; &quot;Could not get hwservicemanager.&quot;; signalExceptionForError(env, UNKNOWN_ERROR, true /* canThrowRemoteException */); return NULL; &#125; const char *ifaceNameCStr = env-&gt;GetStringUTFChars(ifaceNameObj, NULL); if (ifaceNameCStr == NULL) &#123; return NULL; // XXX exception already pending? &#125; std::string ifaceName(ifaceNameCStr); env-&gt;ReleaseStringUTFChars(ifaceNameObj, ifaceNameCStr); ::android::hardware::hidl_string ifaceNameHStr; ifaceNameHStr.setToExternal(ifaceName.c_str(), ifaceName.size()); const char *serviceNameCStr = env-&gt;GetStringUTFChars(serviceNameObj, NULL); if (serviceNameCStr == NULL) &#123; return NULL; // XXX exception already pending? &#125; std::string serviceName(serviceNameCStr); env-&gt;ReleaseStringUTFChars(serviceNameObj, serviceNameCStr); ::android::hardware::hidl_string serviceNameHStr; serviceNameHStr.setToExternal(serviceName.c_str(), serviceName.size()); // 判断当前service是直通式（C/S在同一进程）还是跨进程的binder类型 Return&lt;IServiceManager::Transport&gt; transportRet = manager-&gt;getTransport(ifaceNameHStr, serviceNameHStr); .... IServiceManager::Transport transport = transportRet; if (transport != IServiceManager::Transport::HWBINDER &amp;&amp; !vintfLegacy) &#123; LOG(ERROR) &lt;&lt; &quot;service &quot; &lt;&lt; ifaceName &lt;&lt; &quot; declares transport method &quot; &lt;&lt; toString(transport) &lt;&lt; &quot; but framework expects hwbinder.&quot;; signalExceptionForError(env, UNKNOWN_ERROR, true /* canThrowRemoteException */); return NULL; &#125; // 返回一个BpHwBinder(handle)对象 Return&lt;sp&lt;hidl::base::V1_0::IBase&gt;&gt; ret = manager-&gt;get(ifaceNameHStr, serviceNameHStr); if (!ret.isOk()) &#123; signalExceptionForError(env, UNKNOWN_ERROR, true /* canThrowRemoteException */); return NULL; &#125; //对于远程代理对象，toBinder返回的是一个downcast后的`IBinder`对象（BpHwBinder) sp&lt;hardware::IBinder&gt; service = hardware::toBinder&lt; hidl::base::V1_0::IBase, hidl::base::V1_0::BpHwBase&gt;(ret); if (service == NULL) &#123; signalExceptionForError(env, NAME_NOT_FOUND); return NULL; &#125; LOG(INFO) &lt;&lt; &quot;Starting thread pool.&quot;; ::android::hardware::ProcessState::self()-&gt;startThreadPool(); // 返回一个HwRemoteBinder(BpHwBinder(handle)) return JHwRemoteBinder::NewObject(env, service);&#125;// staticjobject JHwRemoteBinder::NewObject( JNIEnv *env, const sp&lt;hardware::IBinder&gt; &amp;binder) &#123; ScopedLocalRef&lt;jclass&gt; clazz(env, FindClassOrDie(env, CLASS_PATH)); // XXX Have to look up the constructor here because otherwise that static // class initializer isn&#x27;t called and gProxyOffsets.constructID is undefined :( jmethodID constructID = GetMethodIDOrDie(env, clazz.get(), &quot;&lt;init&gt;&quot;,