ad_rwlock_t *radioServiceRwlockPtr = radio::getRadioServiceRwlock(mSlotId); int ret = pthread_rwlock_wrlock(radioServiceRwlockPtr); assert(ret == 0); mRadioResponse = radioResponseParam; mRadioIndication = radioIndicationParam;//&lt; RNTFIX:: mSecRadioResponse = NULL; mSecRadioIndication = NULL;//&gt; RNTFIX mCounterRadio[mSlotId]++; ret = pthread_rwlock_unlock(radioServiceRwlockPtr); assert(ret == 0); // client is connected. Send initial indications. android::onNewCommandConnect((RIL_SOCKET_ID) mSlotId); return Void();&#125; RILD发送消息告知RILJ通信建立成功： 12345678910111213141516171819202122232425262728293031 void onNewCommandConnect(RIL_SOCKET_ID socket_id) &#123; // Inform we are connected and the ril version int rilVer = s_callbacks.version; RIL_UNSOL_RESPONSE(RIL_UNSOL_RIL_CONNECTED, &amp;rilVer, sizeof(rilVer), socket_id); // implicit radio state changed RIL_UNSOL_RESPONSE(RIL_UNSOL_RESPONSE_RADIO_STATE_CHANGED, NULL, 0, socket_id); // Send last NITZ time data, in case it was missed if (s_lastNITZTimeData != NULL) &#123; resendLastNITZTimeData(socket_id); &#125; // Get version string if (s_callbacks.getVersion != NULL) &#123; const char *version; version = s_callbacks.getVersion(); RLOGI(&quot;RIL Daemon version: %s
&quot;, version); property_set(PROPERTY_RIL_IMPL, version); &#125; else &#123; RLOGI(&quot;RIL Daemon version: unavailable
&quot;); property_set(PROPERTY_RIL_IMPL, &quot;unavailable&quot;); &#125;&#125; 参考资料 http://sniffer.site/2016/11/29/Android-RILD详解/ http://sniffer.site/2016/11/29/Android-RIL概述/
